import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as i,af as n}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const f=JSON.parse('{"title":"MiniMax Agent tutorial","description":"Open agent.minimax.io, pick Lightning or Pro, and send the first long-horizon task. This is not the MiniMax Code desktop tutorial.","frontmatter":{"title":"MiniMax Agent tutorial","description":"Open agent.minimax.io, pick Lightning or Pro, and send the first long-horizon task. This is not the MiniMax Code desktop tutorial.","domain":"product","tags":["coding-agent"],"role":"tutorial"},"headers":[],"relativePath":"products/minimax-agent/minimax-agent.md","filePath":"products/minimax-agent/minimax-agent.md","lastUpdated":1787107158000}'),o={name:"products/minimax-agent/minimax-agent.md"};function r(s,e,l,h,d,p){return i(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="minimax-agent-tutorial" tabindex="-1">MiniMax Agent tutorial <a class="header-anchor" href="#minimax-agent-tutorial" aria-label="Permalink to &quot;MiniMax Agent tutorial&quot;">​</a></h1><blockquote><p>Goal: finish one deliverable in the web workbench in about 15 minutes.</p><p>Non-goals: install MiniMax Code, configure a workspace / terminal / permission mode, or explain model internals. Desktop: <a href="https://agent.minimaxi.com/docs/code/welcome" target="_blank" rel="noreferrer">Code welcome</a>. Internals: <a href="https://llm.zenheart.site/chapters/" target="_blank" rel="noreferrer">Learn LLM</a>.</p></blockquote><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>You can open <a href="https://agent.minimax.io/" target="_blank" rel="noreferrer">agent.minimax.io</a> or <a href="https://agent.minimaxi.com/" target="_blank" rel="noreferrer">agent.minimaxi.com</a>.</li><li>A MiniMax account. The button on the product page is <strong>Sign in</strong> / <strong>登录</strong>.</li><li>No local repo. No CLI.</li></ul><h2 id="learning-objectives" tabindex="-1">Learning objectives <a class="header-anchor" href="#learning-objectives" aria-label="Permalink to &quot;Learning objectives&quot;">​</a></h2><ol><li>Tell Agent (web) apart from Code (desktop).</li><li>Pick Lightning or Pro from task length.</li><li>Send a task that names a deliverable, and know when to add Agent Team or a skill.</li></ol><h2 id="what-it-is" tabindex="-1">What it is <a class="header-anchor" href="#what-it-is" aria-label="Permalink to &quot;What it is&quot;">​</a></h2><p>MiniMax Agent is a general-purpose agent in the browser. The <a href="https://www.minimaxi.com/news/minimax-agent" target="_blank" rel="noreferrer">launch post</a> designs it as a &quot;reliable person&quot; and lists three bars:</p><table tabindex="0"><thead><tr><th>Bar</th><th>Official wording</th></tr></thead><tbody><tr><td>Programming</td><td>More components and complex jumps; simulate user actions for tests; care about UI</td></tr><tr><td>Multimodal</td><td>Understand long text, video, audio, images; built-in image / audio / video generation</td></tr><tr><td>MCP</td><td>Built-in MiniMax MCP; also lists GitHub / GitLab / Slack / Figma</td></tr></tbody></table><p>The home page currently says &quot;MiniMax makes your work easier&quot; and exposes an <strong>Agent Team</strong> control plus a model picker (MiniMax-M3 was visible on 2026-08-19).</p><p>It is <strong>not</strong>:</p><ul><li>MiniMax Code (desktop; <a href="https://agent.minimaxi.com/docs/code/welcome" target="_blank" rel="noreferrer">welcome</a>: conversation, project workspace, files, terminal, browser, skills, memory, and automation in one local environment)</li><li>MiniMax Design / Hub (creation canvas)</li><li>Hailuo, Xingye / Talkie, or Audio (see the <a href="./">map</a>)</li></ul><h2 id="step-1-open-the-workbench" tabindex="-1">Step 1: Open the workbench <a class="header-anchor" href="#step-1-open-the-workbench" aria-label="Permalink to &quot;Step 1: Open the workbench&quot;">​</a></h2><ol><li>Open <a href="https://agent.minimax.io/" target="_blank" rel="noreferrer">agent.minimax.io</a> (international) or <a href="https://agent.minimaxi.com/" target="_blank" rel="noreferrer">agent.minimaxi.com</a> (China).</li><li>Click <strong>Sign in</strong>.</li><li>Describe the goal in the home input. On 2026-08-19 the international home showed shortcuts such as <strong>Video generation</strong>, <strong>Document</strong>, <strong>Website</strong>, <strong>Image Generation</strong>.</li><li>If you need the desktop app, the home page has <strong>Download desktop</strong>. The <a href="https://agent.minimaxi.com/download" target="_blank" rel="noreferrer">download page</a> is currently titled <strong>MiniMax Code</strong>. That is the desktop brand, not the next step of this tutorial.</li></ol><h2 id="step-2-pick-lightning-or-pro" tabindex="-1">Step 2: Pick Lightning or Pro <a class="header-anchor" href="#step-2-pick-lightning-or-pro" aria-label="Permalink to &quot;Step 2: Pick Lightning or Pro&quot;">​</a></h2><p>From the <a href="https://www.minimaxi.com/news/minimax-m2" target="_blank" rel="noreferrer">M2 post</a> (EN: <a href="https://www.minimaxi.com/en/news/minimax-m2" target="_blank" rel="noreferrer">M2 &amp; Agent</a>):</p><table tabindex="0"><thead><tr><th>Mode</th><th>Official positioning</th><th>Official examples</th></tr></thead><tbody><tr><td><strong>Lightning</strong></td><td>High-efficiency, high-speed agent</td><td>Conversational Q&amp;A, lightweight search, simple coding</td></tr><tr><td><strong>Pro</strong></td><td>Professional agent quality on complex, long-running tasks</td><td>In-depth research, full-stack development, PPTs / reports, web development</td></tr></tbody></table><p>How to choose:</p><ul><li>One question, one lookup, a small code tweak → Lightning.</li><li>A sourced report, a slide deck, a working page, a full-stack handoff → Pro.</li><li>Unsure → Lightning first. Switch to Pro if the deliverable is thin. Do not default every task to Pro.</li></ul><p>These names come from the official product post. The exact toggle label is whatever you see after sign-in. This page does not invent a click path.</p><h2 id="step-3-send-the-first-task" tabindex="-1">Step 3: Send the first task <a class="header-anchor" href="#step-3-send-the-first-task" aria-label="Permalink to &quot;Step 3: Send the first task&quot;">​</a></h2><p>The official line is to show the requirement. Put the <strong>deliverable</strong> in the first message.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Research the official difference between MiniMax Agent and MiniMax Code.</span></span>
<span class="line"><span>Use only pages on minimaxi.com, minimax.io, agent.minimaxi.com, and agent.minimax.io.</span></span>
<span class="line"><span>Deliver:</span></span>
<span class="line"><span>1. A Markdown comparison table (product, entry, fit, not-fit)</span></span>
<span class="line"><span>2. An 8-slide HTML outline for frontend engineers</span></span>
<span class="line"><span>Do not describe model internals.</span></span></code></pre></div><p>Watch three things:</p><ol><li>Does the agent confirm the goal before dumping text?</li><li>Are citations stable official URLs? The <a href="https://agent.minimaxi.com/docs/techblog/agent-team.md" target="_blank" rel="noreferrer">Agent Team</a> note says formal sources should use stable URLs; search caches are clues only.</li><li>Can you open or download the file? A chat transcript is not the deliverable.</li></ol><p>Use <strong>Pro</strong> for this first task. It is long-horizon research with two outputs.</p><h2 id="step-4-turn-on-agent-team-only-for-work-that-must-split" tabindex="-1">Step 4: Turn on Agent Team only for work that must split <a class="header-anchor" href="#step-4-turn-on-agent-team-only-for-work-that-must-split" aria-label="Permalink to &quot;Step 4: Turn on Agent Team only for work that must split&quot;">​</a></h2><p>The <a href="https://agent.minimaxi.com/docs/techblog/agent-team.md" target="_blank" rel="noreferrer">Agent Team article</a>: the user still sends one message; the system decides whether to split, which roles can run in parallel, and which results must be verified.</p><p>Official roles:</p><ul><li><strong>Leader</strong> — turn the goal into a task structure.</li><li><strong>Worker</strong> — run a sub-task; tools / context / output contract can differ.</li><li><strong>Verifier</strong> — turn &quot;done&quot; into &quot;shippable&quot;. Officially adversarial to the Worker.</li></ul><p>Turn Team on when:</p><ul><li>You need parallel research, cross-checks, then a synthesis.</li><li>A document must go from &quot;generated&quot; to &quot;shippable&quot; (official office pipeline: Planner / Writer / Formatter / Evaluator).</li><li>You are on IM and cannot stare at a spinner. Officially the lead agent replies first and runs the rest in the background.</li></ul><p>Leave Team off when:</p><ul><li>You are fixing a typo, checking one fact, or making one image. The official article says a single agent is cheaper there.</li><li>You have not written an acceptance bar. Team amplifies a vague goal.</li></ul><p>The home page has an <strong>Agent Team</strong> control. A <code>/team</code> mention appears in the desktop changelog. On the web, use the control you can see. Do not copy Code slash commands into this tutorial as required steps.</p><h2 id="step-5-extend-with-the-skill-marketplace" tabindex="-1">Step 5: Extend with the skill marketplace <a class="header-anchor" href="#step-5-extend-with-the-skill-marketplace" aria-label="Permalink to &quot;Step 5: Extend with the skill marketplace&quot;">​</a></h2><p>Open <a href="https://agent.minimaxi.com/skills" target="_blank" rel="noreferrer">agent.minimaxi.com/skills</a> (also on the <code>.io</code> host). Official copy: explore, install, and use capabilities built by developers and the community. Custom creation and GitHub import are listed.</p><p>On 2026-08-19 the marketplace showed first-party skills for decks, industry research, DOCX, long-form posts, image prompts, equity analysis, Excel, and PowerPoint. <strong>The catalog changes.</strong> Trust the live page.</p><p>How to use it:</p><ol><li>Search for an existing skill before starting a long task.</li><li>After you have run the same flow twice, consider saving it as a skill. The Team article treats memory and Skill as the long-term value of a run.</li><li>Do not merge this page with the Code plugin marketplace. Plugin launch notes live in the Code changelog.</li></ol><h2 id="billing-quote-both-official-lines" tabindex="-1">Billing: quote both official lines <a class="header-anchor" href="#billing-quote-both-official-lines" aria-label="Permalink to &quot;Billing: quote both official lines&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Source</th><th>Wording</th><th>How to read it</th></tr></thead><tbody><tr><td><a href="https://www.minimaxi.com/en/news/minimax-m2" target="_blank" rel="noreferrer">M2 post</a></td><td>MiniMax Agent is offered free &quot;until our servers can&#39;t keep up&quot;</td><td>A time-boxed launch policy, not an SLA</td></tr><tr><td><a href="https://agent.minimaxi.com/skills" target="_blank" rel="noreferrer">Skill marketplace</a></td><td>Unified billing through Token Plan</td><td>Quota is whatever the signed-in plan page shows</td></tr><tr><td><a href="https://agent.minimaxi.com/download" target="_blank" rel="noreferrer">Download page</a></td><td>Plus ¥49 / Max ¥119 / Ultra ¥469</td><td>The page brand is MiniMax Code. Do not treat those prices as Agent-web-only</td></tr></tbody></table><p>Use <strong>See Plan and pricing</strong> after sign-in. This page does not invent token-pack sizes.</p><h2 id="common-pitfalls" tabindex="-1">Common pitfalls <a class="header-anchor" href="#common-pitfalls" aria-label="Permalink to &quot;Common pitfalls&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Pitfall</th><th>Do this instead</th></tr></thead><tbody><tr><td>Turning this tutorial into a Code CLI guide</td><td>Stop at the browser. Workspace / terminal / Coding mode belong in #72</td></tr><tr><td>Pro or Team on every prompt</td><td>Lightning for short Q&amp;A</td></tr><tr><td>Citing a reseller blog</td><td>Official stable URLs only</td></tr><tr><td>Writing &quot;always free&quot;</td><td>Link the live plan page</td></tr><tr><td>Treating Hub as another name for Agent</td><td>Hub currently lands on Design</td></tr><tr><td>Explaining MSA / attention</td><td><a href="https://llm.zenheart.site/chapters/" target="_blank" rel="noreferrer">Learn LLM</a></td></tr></tbody></table><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li>Recipes: <a href="./minimax-agent-cookbook.html">Cookbook</a></li><li>Entries and sources: <a href="./minimax-agent-cheatsheet.html">Cheatsheet</a></li><li>Names: <a href="./minimax-agent-glossary.html">Glossary</a></li><li>Local repo: <a href="https://agent.minimaxi.com/docs/code/welcome" target="_blank" rel="noreferrer">Code welcome</a></li></ul>`,47)])])}const b=t(o,[["render",r]]);export{f as __pageData,b as default};
